   ("=", "{F} En x + y = 6, si x vale 5, ¿cuánto vale y?", "6-5", "Se resta de 6 el valor de x.", ""),
   ("abc", "{F} ¿Cuál de estos puntos está en la recta r?", "(3, 3)", "(3, 4)", "(2, 2)", "Solo en (3, 3) las coordenadas suman 6; los otros suman 7 y 4."),
   ("=", "{F} En la recta s (x − y = 2), si y vale 1, ¿cuánto vale x?", "2+1", "En s, x es dos unidades mayor que y.", ""),
   ("ab", "{F} Los puntos (1, 5) y (5, 1), ¿están los dos en la recta r?", "Sí: en ambos las coordenadas suman 6", "No: solo uno de los dos está", "Reemplazando, 1 + 5 y 5 + 1 dan 6 en los dos casos."),
   ("{F} Escribe el punto de la recta r cuya coordenada y es el doble de x.", "(2, 4)", "Con y igual a 2x queda 3x = 6, entonces x vale 2 e y vale 4."),
   ("=", "{F} En la recta s (x − y = 2), si x vale 5, ¿cuánto vale y?", "5-2", "En s, y es dos unidades menor que x.", ""),
   ("abc", "{F} ¿Cuál punto está en la recta s?", "(4, 2)", "(2, 4)", "(3, 0)", "En (4, 2) la resta 4 − 2 da 2; los otros dan −2 y 3."),
   ("abc", "{F} El punto (4, 2) está en r y también en s. ¿Qué significa?", "Cumple las dos ecuaciones a la vez", "Que las rectas son paralelas", "Que la ecuación r es falsa", "Un punto de las dos rectas cumple las dos ecuaciones: es la solución del sistema."),
   ("=", "{F} Un punto de r tiene las dos coordenadas iguales. ¿Cuánto vale cada una?", "6//2", "Si x = y, entonces dos veces x es 6.", ""),
